export async function countPendingClosings(): Promise<number> {
  if (!isSupabaseConfigured) return 0;
  const supabase = getSupabase();
  const { count, error } = await supabase
    .from("daily_closings")
    .select("*", { count: "exact", head: true })
    .eq("status", "pending");
