export async function approveClosing(
  id: string,
  comment?: string,
): Promise<void> {
  if (!isSupabaseConfigured) {
    throw new Error("لم يتم إعداد Supabase بعد.");
  }
  const supabase = getSupabase();
  const now = new Date().toISOString();
  const { error } = await supabase
    .from("daily_closings")
    .update({
      status: "approved",
      auditor_comment: comment ?? null,
      auditor_reviewed_at: now,
      updated_at: now,
    })
    .eq("id", id);
  if (error) {
    console.error("[closings] approve update failed", error.message);
    throw new Error("تعذّر تحديث حالة الإقفال.");
  }
  const { error: auditError } = await supabase
    .from("daily_closing_audit_logs")
    .insert({
      closing_id: id,
      actor_role: "auditor",
      action: "approved",
      comment: comment ?? null,
    });
  if (auditError) {
    console.error("[closings] approve audit insert failed", auditError.message);
    throw new Error("تم تحديث الحالة لكن تعذّر تسجيل سجل التدقيق.");
  }
}

export async function rejectClosing(
  id: string,
  comment: string,
): Promise<void> {
  if (!isSupabaseConfigured) {
    throw new Error("لم يتم إعداد Supabase بعد.");
  }
  if (!comment.trim()) {
    throw new Error("سبب الرفض مطلوب.");
  }
  const supabase = getSupabase();
  const now = new Date().toISOString();
  const { error } = await supabase
    .from("daily_closings")
    .update({
      status: "rejected",
      auditor_comment: comment,
      auditor_reviewed_at: now,
      updated_at: now,
    })
    .eq("id", id);
  if (error) {
    console.error("[closings] reject update failed", error.message);
    throw new Error("تعذّر تحديث حالة الإقفال.");
  }
  const { error: auditError } = await supabase
    .from("daily_closing_audit_logs")
    .insert({
      closing_id: id,
      actor_role: "auditor",
      action: "rejected",
      comment,
    });
  if (auditError) {
    console.error("[closings] reject audit insert failed", auditError.message);
    throw new Error("تم تحديث الحالة لكن تعذّر تسجيل سجل التدقيق.");
  }
}
