    for (const c of list) {
      totals.grossSales += c.reviewedData?.grossSales ?? 0;
      totals.cashActualHanded += c.reviewedData?.cashActualHanded ?? 0;
      const soe = c.reviewedData?.shortageOrExcess ?? computeShortageOrExcess(
        c.reviewedData?.cashActualHanded ?? 0,
        c.reviewedData?.cashSystem ?? 0,
      );
      totals.shortageOrExcess += soe;
      totals.reversedTransactions += c.reviewedData?.reversedTransactions ?? 0;
    }
    return totals;
  }, [list]);

  const byBranch = useMemo(() => {
    const m = new Map<string, { name: string; gross: number; cash: number; soe: number; rev: number; count: number }>();
    for (const c of list) {
