        name: c.branchName,
        gross: 0,
        cash: 0,
        soe: 0,
        rev: 0,
        count: 0,
      };
      cur.gross += c.reviewedData?.grossSales ?? 0;
      cur.cash += c.reviewedData?.cashActualHanded ?? 0;
      const soe = c.reviewedData?.shortageOrExcess ?? computeShortageOrExcess(
        c.reviewedData?.cashActualHanded ?? 0,
