          c.reviewedData?.cashActualHanded ?? 0,
          c.reviewedData?.cashSystem ?? 0,
        )),
        String(c.reviewedData?.reversedTransactions ?? 0),
      ]),
    ];
    const csv = rows
      .map((r) => r.map((c) => `"${c.replace(/"/g, '""')}"`).join(","))
